def score(answers, tie=None):
 if not isinstance(answers,list) or len(answers)!=12 or any(type(a) is not int or a not in range(4) for a in answers):
  raise ValueError('กรุณาตอบให้ครบทั้ง 12 ข้อ')
 scores=[answers.count(i) for i in range(4)]
 tied=[i for i in range(4) if scores[i]==max(scores)]
 if len(tied)>1 and (type(tie) is not int or tie not in tied): return scores,tied,None
 return scores,tied,tied[0] if len(tied)==1 else tie
